        'uptime_heading' => 'അപ്ടൈമും സേവന ചരിത്രവും',
        'uptime_p1_html' => 'ഓരോ സേവനത്തിനും അതിന്റെ കാർഡിൽ <strong>History and uptime</strong> ലിങ്ക് ഉണ്ട്. ഇത് കഴിഞ്ഞ 7, 30, 90 അല്ലെങ്കിൽ 365 ദിവസത്തെ ഒരു ദിവസം-തോറുമുള്ള സ്ട്രിപ്പ്, ആ കാലയളവിൽ സേവനം ലഭ്യമായിരുന്ന ശതമാനം, കൂടാതെ ഓരോ ആഘാത നിലവാരത്തിലും ചെലവഴിച്ച കാലയളവും കാണിക്കുന്നു.',
        'uptime_p2_html' => 'ഇത് നിങ്ങൾ പരിപാലിക്കേണ്ട ഒരു പ്രത്യേക ലോഗ് അല്ല: ഇത് നിങ്ങളുടെ സംഭവങ്ങളിൽ നിന്നാണ് കണക്കാക്കുന്നത്. അതായത് ഈ ഫീച്ചർ ഉണ്ടാകുന്നതിന് മുമ്പ് സംഭവിച്ച തടസ്സങ്ങളും ഇത് ഉൾക്കൊള്ളുന്നു &mdash; പക്ഷേ അതിനർത്ഥം <strong>സംഭവങ്ങൾ രേഖപ്പെടുത്തുന്ന രീതി അനുസരിച്ച് മാത്രമേ കണക്കുകൾ ശരിയാകൂ</strong> എന്നാണ്, അതാണ് ഈ വിഭാഗത്തിന്റെ ബാക്കി ഭാഗം വിശദീകരിക്കുന്നത്.',
        'uptime_record_heading' => 'ചരിത്രം ശരിയാകാൻ ഒരു തടസ്സം രേഖപ്പെടുത്തൽ',
        'uptime_record_p_html' => 'ഒരു സംഭവം ഒരു സേവനത്തെ ഡൗൺടൈമായി കണക്കാക്കുന്ന ഒരു നിലവാരത്തിൽ എത്തിക്കുന്ന നിമിഷം മുതൽ, മറ്റെന്തെങ്കിലും പറയുന്നത് വരെ ആ സേവനം ഡൗൺ ആയി കണക്കാക്കപ്പെടുന്നു. നിങ്ങൾ ഒരു സംഭവം സേവ് ചെയ്യുമ്പോഴെല്ലാം, ഏതൊക്കെ സേവനങ്ങൾ ഏത് നിലവാരത്തിലായിരുന്നു എന്നതിന്റെ ഒരു സ്നാപ്‌ഷോട്ട് FreeITSM രേഖപ്പെടുത്തുന്നു &mdash; അതിനാൽ കൃത്യമായ ചരിത്രം ലഭിക്കാനുള്ള വഴി, കാര്യങ്ങൾ മാറുമ്പോൾ <strong>സംഭവം അപ്ഡേറ്റ് ചെയ്യുക</strong> എന്നത് മാത്രമാണ്.',
        'uptime_step1_html' => 'ബാധിച്ച എല്ലാ സേവനങ്ങളോടും അവയുടെ ആഘാത നിലവാരത്തോടും കൂടി <strong>സംഭവം ഉയർത്തുക</strong>. അതാണ് ആരംഭ സമയം.',
        'uptime_step2_html' => 'കാര്യങ്ങൾ മാറുമ്പോഴെല്ലാം <strong>വീണ്ടും സേവ് ചെയ്യുക</strong> &mdash; ഒരു സേവനം മോശമാകുന്നു, മെച്ചപ്പെടുന്നു, അല്ലെങ്കിൽ തിരികെ വരുന്നു. ആ സേവനത്തിന്റെ ആഘാത നിലവാരം മാറ്റുക, അല്ലെങ്കിൽ പൂർണ്ണമായും പുനഃസ്ഥാപിച്ചെങ്കിൽ സംഭവത്തിൽ നിന്ന് നീക്കം ചെയ്യുക. ഓരോ സേവിനും ടൈംസ്റ്റാമ്പ് ഉണ്ട്, അതിനാൽ ഒരു ദിവസം Major Outage-ലും എട്ട് മണിക്കൂർ Degraded-ലും ആയിരുന്ന ഒരു സേവനം കൃത്യമായി അതുപോലെ രേഖപ്പെടുത്തും.',
        'uptime_step3_html' => 'എല്ലാം തിരികെ വന്നാൽ <strong>സംഭവം പരിഹരിക്കുക</strong>. ഇപ്പോഴും ലിസ്റ്റ് ചെയ്തിരിക്കുന്ന എന്തിനും അതാണ് അവസാന സമയം.',
        'uptime_resolve_note_html' => 'സേവനങ്ങൾ ഓരോന്നായി നീക്കം ചെയ്യേണ്ട ആവശ്യമില്ല &mdash; പക്ഷേ അങ്ങനെ ചെയ്താൽ, ഓരോന്നും മുഴുവൻ സംഭവം പരിഹരിക്കുമ്പോൾ അല്ല, ആ നിമിഷം തന്നെ കണക്കാക്കുന്നത് നിർത്തും. &ldquo;ഫയൽ സെർവർ രണ്ട് ദിവസം ഡൗൺ ആയിരുന്നു&rdquo;, &ldquo;എല്ലാം മൂന്ന് ദിവസം ഡൗൺ ആയിരുന്നു&rdquo; എന്നിവ തമ്മിലുള്ള വ്യത്യാസം അതാണ്.',
        'uptime_counts_heading' => 'എന്താണ് ഡൗൺടൈമായി കണക്കാക്കുന്നത്',
        'uptime_counts_p_html' => '<strong>Settings &rarr; Impact levels</strong>-ൽ ഓരോ ആഘാത നിലവാരവും ഇത് സ്വയം തീരുമാനിക്കുന്നു. Major Outage, Partial Outage, Degraded എന്നിവ സ്ഥിരസ്ഥിതിയായി കണക്കാക്കും; Maintenance, Operational, No Disruption എന്നിവ കണക്കാക്കില്ല. ആസൂത്രിത മെയിന്റനൻസ് മനഃപൂർവ്വം ഒഴിവാക്കിയിരിക്കുന്നു &mdash; ഇത് കണക്കാക്കുന്നത് നന്നായി പ്രവർത്തിക്കുന്ന ഒരു സേവനത്തെ അവഗണിക്കപ്പെട്ട ഒന്നിനെക്കാൾ മോശമായി കാണിക്കും. നിങ്ങൾ സ്വയം ചേർക്കുന്ന ഏത് നിലവാരവും നിങ്ങൾ മറ്റൊന്ന് പറയുന്നതുവരെ കണക്കാക്കും.',
        'uptime_reading_heading' => 'സ്ട്രിപ്പ് വായിക്കുന്നത്',
        'uptime_read_green_html' => '<strong>പച്ച</strong> &mdash; ആ ദിവസം ഒരു സംഭവവും സേവനത്തെ ബാധിച്ചില്ല.',
        'uptime_read_red_html' => '<strong>ചുവപ്പ്</strong> &mdash; ഒരു സംഭവം അപ്ടൈമിനെതിരെ കണക്കാക്കി. നിറം ആഘാത നിലവാരമാണ്; ഏതെന്ന് കാണാൻ ഹോവർ ചെയ്യുക.',
        'uptime_read_grey_html' => '<strong>ചാര നിറം</strong> &mdash; ഒരു സംഭവം സേവനത്തെ ബാധിച്ചെങ്കിലും, ആസൂത്രിത മെയിന്റനൻസ് പോലെ കണക്കാക്കാത്ത ഒരു നിലവാരത്തിലായിരുന്നു. ഏത് നിലവാരമായിരുന്നു എന്ന് കാണാൻ ഹോവർ ചെയ്യുക.',
        'uptime_tip_html' => 'നിങ്ങൾ പ്രതീക്ഷിച്ചതിലും വളരെ മോശം അപ്ടൈം കാണിക്കുന്ന ഒരു സേവനം സാധാരണയായി ആരും പരിഹരിക്കാത്ത ഒരു സംഭവമാണ് &mdash; തുറന്ന ഒരു സംഭവം അടയ്ക്കുന്നതുവരെ കണക്കാക്കും. കണക്ക് തെറ്റാണെന്ന് കരുതുന്നതിന് മുമ്പ് സംഭവ ലിസ്റ്റ് പരിശോധിക്കുക.',
        'nav_tips' => 'പെട്ടെന്നുള്ള നുറുങ്ങുകൾ',
        'hero_title' => 'സേവന നില ഗൈഡ്',
        'hero_sub' => 'നിങ്ങളുടെ ഐടി സേവനങ്ങൾ നിരീക്ഷിക്കുക, സംഭവങ്ങൾ അറിയിക്കുക, പങ്കാളികളെ തത്സമയം വിവരം നൽകുക.',
        'overview_heading' => 'അവലോകനം',
        'overview_intro' => 'നിങ്ങളുടെ സ്ഥാപനം ആശ്രയിക്കുന്ന എല്ലാ ഐടി സേവനത്തിന്റെയും ആരോഗ്യത്തിന്റെ കേന്ദ്രീകൃത കാഴ്ച സേവന നില മൊഡ്യൂൾ നൽകുന്നു. എന്തെങ്കിലും തെറ്റ് സംഭവിക്കുമ്പോൾ, നിങ്ങൾക്ക് സംഭവങ്ങൾ രേഖപ്പെടുത്താനും ബാധിച്ച സേവനങ്ങൾ പുതുക്കാനും പരിഹാര പ്രക്രിയയിലുടനീളം ഉപയോക്താക്കളെ വിവരം നൽകാനും കഴിയും.',
        'feature_dashboard_title' => 'നില ഡാഷ്ബോർഡ്',
        'feature_dashboard_desc' => 'ഓരോ സേവനത്തിന്റെയും നിലവിലെ ആരോഗ്യം ഒറ്റനോട്ടത്തിൽ കാണുക. ഓരോ സേവനവും പ്രവർത്തനക്ഷമമാണോ, ക്ഷയിച്ചതാണോ, പരിപാലനത്തിലാണോ, അതോ തടസ്സം നേരിടുന്നുണ്ടോ എന്ന് നിറം കോഡ് ചെയ്ത ബാഡ്ജുകൾ കാണിക്കുന്നു.',
        'feature_incident_title' => 'സംഭവ ട്രാക്കിംഗ്',
        'feature_incident_desc' => 'തലക്കെട്ടുകൾ, നില പുതുക്കലുകൾ, അഭിപ്രായങ്ങൾ എന്നിവയോടെ സംഭവങ്ങൾ രേഖപ്പെടുത്തുക. ഓരോ സംഭവത്തിലും ബാധിച്ച സേവനങ്ങൾ ലിങ്ക് ചെയ്യുക, അങ്ങനെ എന്ത് ബാധിച്ചു, എന്തുകൊണ്ട് എന്ന് എല്ലാവർക്കും കൃത്യമായി അറിയാം.',
        'feature_management_title' => 'സേവന കൈകാര്യം',
        'feature_management_desc' => 'ക്രമീകരണങ്ങളിൽ നിങ്ങളുടെ സേവന കാറ്റലോഗ് ക്രമീകരിക്കുക. പേരുകൾ, വിവരണങ്ങൾ, പ്രദർശന ക്രമം എന്നിവയോടെ സേവനങ്ങൾ ചേർക്കുക. നിങ്ങളുടെ ഇൻഫ്രാസ്ട്രക്ചർ വികസിക്കുമ്പോൾ സേവനങ്ങൾ സജീവമാക്കുകയോ നിഷ്ക്രിയമാക്കുകയോ ചെയ്യുക.',
        'feature_comms_title' => 'ആശയവിനിമയം',
        'feature_comms_desc' => 'തത്സമയ നില പുതുക്കലുകൾ ഉപയോഗിച്ച് പങ്കാളികളെ വിവരം നൽകുക. ഓരോ സംഭവത്തിനും ഒരു നിലയും അഭിപ്രായ പാതയും ഉണ്ട്, അതിനാൽ ഉപയോക്താക്കൾക്ക് സർവീസ് ഡെസ്കിനെ പിന്തുടരാതെ പരിഹാര പുരോഗതി പിന്തുടരാനാകും.',
        'dashboard_heading' => 'നില ഡാഷ്ബോർഡ്',
        'dashboard_p1' => 'സേവന നില മൊഡ്യൂൾ തുറക്കുമ്പോൾ ആദ്യം കാണുന്നത് ഡാഷ്ബോർഡാണ്. അത് സേവന കാർഡുകളുടെ ഒരു ഗ്രിഡ് പ്രദർശിപ്പിക്കുന്നു, ഓരോന്നും സേവനത്തിന്റെ പേര്, ഒരു ഹ്രസ്വ വിവരണം, അതിന്റെ നിലവിലെ ഏറ്റവും മോശം നില പ്രതിഫലിപ്പിക്കുന്ന നിറം കോഡ് ചെയ്ത ആഘാത ബാഡ്ജ് എന്നിവ കാണിക്കുന്നു. ഗ്രിഡിന് താഴെ, അടുത്തിടെയുള്ളതും സജീവവുമായ എല്ലാ സംഭവങ്ങളും പട്ടികപ്പെടുത്തുന്ന സംഭവ പട്ടിക ഉണ്ട്.',
        'dashboard_p2_html' => 'ഏതെങ്കിലും സജീവ (പരിഹരിക്കാത്ത) സംഭവത്തിൽ നിന്ന് അതിന് നൽകിയ ഏറ്റവും തീവ്രമായ ആഘാത നിലവാരം ഓരോ സേവന കാർഡും സ്വയം പ്രതിഫലിപ്പിക്കുന്നു. ഒരു സേവനത്തെ ബാധിക്കുന്ന എല്ലാ സംഭവങ്ങളും പരിഹരിക്കുമ്പോൾ, അത് <strong>പ്രവർത്തനക്ഷമം</strong> എന്നതിലേക്ക് മടങ്ങുന്നു.',
        'status_levels' => 'നില നിലവാരങ്ങൾ',
        'level_operational_name' => 'പ്രവർത്തനക്ഷമം',
        'level_operational_desc' => 'അറിയപ്പെടുന്ന പ്രശ്നങ്ങളൊന്നുമില്ലാതെ സേവനം സാധാരണ നിലയിൽ പ്രവർത്തിക്കുന്നു. ആരോഗ്യമുള്ള എല്ലാ സേവനങ്ങൾക്കും ഇതാണ് സ്ഥിരസ്ഥിതി അവസ്ഥ.',
        'level_degraded_name' => 'ക്ഷയിച്ച പ്രകടനം',
        'level_degraded_desc' => 'സേവനം ലഭ്യമാണ്, പക്ഷേ പ്രതീക്ഷിച്ചതിലും വേഗത കുറവായോ കുറഞ്ഞ പ്രവർത്തനക്ഷമതയോടെയോ പ്രവർത്തിക്കുന്നു. ഉപയോക്താക്കൾക്ക് കാലതാമസം ശ്രദ്ധയിൽപ്പെട്ടേക്കാം.',
        'level_maintenance_name' => 'പരിപാലനത്തിലാണ്',
        'level_maintenance_desc' => 'ആസൂത്രണം ചെയ്ത ഡൗൺടൈം അല്ലെങ്കിൽ പരിപാലന വിൻഡോ. ജോലി നടക്കുമ്പോൾ സേവനം താൽക്കാലികമായി ലഭ്യമല്ലാതായേക്കാം.',
        'level_outage_name' => 'വലിയ തടസ്സം',
        'level_outage_desc' => 'സേവനം പൂർണ്ണമായും ലഭ്യമല്ല. ഇതാണ് ഏറ്റവും തീവ്രമായ നില, ഉടനടി അന്വേഷണത്തിന് ഇത് കാരണമാകണം.',
        'dashboard_tip' => 'ആഘാത നിലവാരങ്ങൾ ശ്രേണീബദ്ധമാണ്. ഒരു സേവനം ഒന്നിലധികം സജീവ സംഭവങ്ങളുമായി ലിങ്ക് ചെയ്തിട്ടുണ്ടെങ്കിൽ, ഡാഷ്ബോർഡ് ഏറ്റവും മോശം ആഘാതം കാണിക്കുന്നു. ഉദാഹരണത്തിന്, ഒരു സംഭവം ഒരു സേവനത്തെ ക്ഷയിച്ചതായും മറ്റൊന്ന് വലിയ തടസ്സമായും അടയാളപ്പെടുത്തിയാൽ വലിയ തടസ്സം പ്രദർശിപ്പിക്കും.',
        'services_heading_html' => 'സേവനങ്ങൾ കൈകാര്യം ചെയ്യലും &amp; സംഭവങ്ങൾ രേഖപ്പെടുത്തലും',
        'services_intro' => 'നിങ്ങളുടെ നില പേജിന്റെ അടിസ്ഥാന ഘടകങ്ങളാണ് സേവനങ്ങൾ. ഓരോന്നും നിങ്ങളുടെ ഉപയോക്താക്കൾ ആശ്രയിക്കുന്ന ഒരു ഐടി സേവനത്തെയോ സിസ്റ്റത്തെയോ ഇൻഫ്രാസ്ട്രക്ചർ ഘടകത്തെയോ പ്രതിനിധീകരിക്കുന്നു. എന്തെങ്കിലും തെറ്റ് സംഭവിക്കുമ്പോൾ, നിങ്ങൾ ഒരു സംഭവം സൃഷ്ടിക്കുകയും അത് ബാധിച്ച സേവനങ്ങളുമായി ലിങ്ക് ചെയ്യുകയും ചെയ്യുന്നു.',
        'add_incident_heading' => 'പുതിയ സംഭവം ചേർക്കൽ',
        'add_incident_step1_html' => 'സംഭവ ഫോം തുറക്കാൻ ഡാഷ്ബോർഡിലെ <strong>"പുതിയത്" ക്ലിക്ക് ചെയ്യുക</strong>.',
        'add_incident_step2_html' => '<strong>ഒരു തലക്കെട്ട് നൽകുക</strong> &mdash; പ്രശ്നത്തിന്റെ ഹ്രസ്വവും വ്യക്തവുമായ വിവരണം. ഉദാഹരണത്തിന്: "ഇമെയിൽ ഡെലിവറി കാലതാമസം" അല്ലെങ്കിൽ "VPN ഗേറ്റ്‌വേ എത്തിച്ചേരാനാകുന്നില്ല".',
        'add_incident_step3_html' => '<strong>നില സജ്ജമാക്കുക</strong> &mdash; അന്വേഷിക്കുന്നു, തിരിച്ചറിഞ്ഞു, 3rd Party, നിരീക്ഷിക്കുന്നു, അല്ലെങ്കിൽ പരിഹരിച്ചു എന്നിവയിൽ ഒന്ന് തിരഞ്ഞെടുക്കുക. അന്വേഷിക്കുന്നു എന്നതിൽ തുടങ്ങി കൂടുതൽ അറിയുമ്പോൾ പുതുക്കുക.',
        'add_incident_step4_html' => '<strong>ഒരു അഭിപ്രായം ചേർക്കുക</strong> &mdash; ഇതുവരെ അറിയാവുന്നത്, എടുക്കുന്ന നടപടികൾ, ഉപയോക്താക്കൾക്ക് ലഭ്യമായ പരിഹാരമാർഗങ്ങൾ എന്നിവ വിവരിക്കുക.',
        'add_incident_step5_html' => '<strong>ബാധിച്ച സേവനങ്ങൾ ലിങ്ക് ചെയ്യുക</strong> &mdash; ഒന്നോ അതിലധികമോ സേവനങ്ങൾ ചേർത്ത് ഓരോന്നിനും ആഘാത നിലവാരം തിരഞ്ഞെടുക്കുക (വലിയ തടസ്സം, ഭാഗിക തടസ്സം, ക്ഷയിച്ചത്, പരിപാലനം, പ്രവർത്തനക്ഷമം, അല്ലെങ്കിൽ തടസ്സമില്ല).',
        'add_incident_step6_html' => '<strong>സംരക്ഷിക്കുക</strong> &mdash; സംഭവം പട്ടികയിൽ പ്രത്യക്ഷപ്പെടുകയും ബാധിച്ച സേവന കാർഡുകൾ ഡാഷ്ബോർഡിൽ ഉടനടി പുതുക്കുകയും ചെയ്യുന്നു.',
        'workflow_heading' => 'സംഭവ നില വർക്ക്ഫ്ലോ',
        'workflow_investigating' => 'അന്വേഷിക്കുന്നു',
        'workflow_identified' => 'തിരിച്ചറിഞ്ഞു',
        'workflow_monitoring' => 'നിരീക്ഷിക്കുന്നു',
        'workflow_resolved' => 'പരിഹരിച്ചു',
        'workflow_note_html' => 'മൂലകാരണം ഒരു ബാഹ്യ വെണ്ടറുമായോ ദാതാവുമായോ ബന്ധപ്പെട്ടതാണെങ്കിൽ <strong>3rd Party</strong> ഉപയോഗിക്കുക.',
        'services_tip' => 'പട്ടികയിലെ തലക്കെട്ടിൽ ക്ലിക്ക് ചെയ്ത് നിങ്ങൾക്ക് ഏത് സംഭവവും തിരുത്താം. സാഹചര്യം വികസിക്കുമ്പോൾ നില പുതുക്കുക, പുതിയ അഭിപ്രായങ്ങൾ ചേർക്കുക, അല്ലെങ്കിൽ ബാധിച്ച സേവനങ്ങൾ മാറ്റുക. സംഭവങ്ങൾ പുതുക്കി നിലനിർത്തുന്നതാണ് സുതാര്യമായ ആശയവിനിമയത്തിന്റെ താക്കോൽ.',
        'history_heading' => 'സംഭവ ചരിത്രം',
        'history_p1' => 'ഡാഷ്ബോർഡിലെ സംഭവ പട്ടിക സജീവവും പരിഹരിച്ചതുമായ സംഭവങ്ങൾ കാണിക്കുന്നു, ഇത് സേവന ആരോഗ്യത്തിന്റെ ഒരു സമ്പൂർണ്ണ ടൈംലൈൻ നൽകുന്നു. ഓരോ വരിയും സംഭവ തലക്കെട്ട്, നിലവിലെ നില, ആഘാത നിലവാരങ്ങളോടെ ബാധിച്ച സേവനങ്ങൾ, അവസാനം പുതുക്കിയ സമയമുദ്ര എന്നിവ പ്രദർശിപ്പിക്കുന്നു.',
        'history_field_title_html' => '<strong>തലക്കെട്ട്</strong> &mdash; തിരുത്തലിനായി സംഭവം തുറക്കുന്ന ഒരു ക്ലിക്ക് ചെയ്യാവുന്ന ലിങ്ക്. ചരിത്രം എളുപ്പത്തിൽ പരിശോധിക്കാൻ വ്യക്തവും വിവരണാത്മകവുമായ തലക്കെട്ടുകൾ ഉപയോഗിക്കുക.',
        'history_field_status_html' => '<strong>നില</strong> &mdash; നിലവിലെ അന്വേഷണ ഘട്ടം കാണിക്കുന്ന നിറം കോഡ് ചെയ്ത ബാഡ്ജ് (അന്വേഷിക്കുന്നു, തിരിച്ചറിഞ്ഞു, 3rd Party, നിരീക്ഷിക്കുന്നു, അല്ലെങ്കിൽ പരിഹരിച്ചു).',
        'history_field_affected_html' => '<strong>ബാധിച്ച സേവനങ്ങൾ</strong> &mdash; ഓരോ ലിങ്ക് ചെയ്ത സേവനവും അതിന്റെ ആഘാത നിലവാര നിറത്തോടെ കാണിക്കുന്ന ടാഗ് ചെയ്ത ബാഡ്ജുകൾ. ഒറ്റനോട്ടത്തിൽ എന്ത് ബാധിച്ചു, എത്ര തീവ്രമായി എന്ന് നിങ്ങൾക്ക് കാണാം.',
        'history_field_updated_html' => '<strong>പുതുക്കിയത്</strong> &mdash; ഏറ്റവും പുതിയ മാറ്റത്തിന്റെ സമയമുദ്ര. പരിഹരിച്ച സംഭവങ്ങൾ മങ്ങിയ ടെക്സ്റ്റ് ഉപയോഗിച്ച് ശൈലീകരിച്ചിരിക്കുന്നു, അതിനാൽ സജീവ സംഭവങ്ങൾ ദൃശ്യപരമായി വേറിട്ടു നിൽക്കുന്നു.',
        'history_field_actions_html' => '<strong>Actions</strong> &mdash; സംഭവം തുറക്കാതെ തന്നെ എഡിറ്റ് ചെയ്യുക, പരിഹരിക്കുക അല്ലെങ്കിൽ ഇല്ലാതാക്കുക.',
        'actions_heading' => 'ഒരു സംഭവത്തിൽ നടപടിയെടുക്കൽ',
        'actions_p1' => 'ഓരോ സംഭവത്തിനും <strong>Actions</strong> കോളത്തിൽ മൂന്ന് ബട്ടണുകൾ ഉണ്ട്, അതേ പ്രവർത്തനങ്ങൾ <strong>right-click</strong> മെനുവിലും ഉണ്ട്, അവിടെ അവ വരച്ചതിന് പകരം പേരിലാണ് കാണിക്കുന്നത്. സംഭവത്തിന്റെ തലക്കെട്ട് ഇപ്പോഴും പൂർണ്ണ എഡിറ്ററിലേക്കുള്ള ഒരു ലിങ്കാണ്, ഇപ്പോൾ അതുപോലെ കാണപ്പെടുകയും ചെയ്യുന്നു.',
        'actions_edit' => '<strong>Edit</strong> &mdash; സംഭവം മാറ്റങ്ങൾക്കായി തുറക്കുന്നു: അതിന്റെ തലക്കെട്ട്, നില, അഭിപ്രായം, ഏതൊക്കെ സേവനങ്ങളെ ബാധിക്കുന്നു എന്നിവ.',
        'actions_resolve' => '<strong>Resolve</strong> &mdash; ഒറ്റ ക്ലിക്കിൽ സംഭവത്തെ <em>resolved</em> എന്ന് അടയാളപ്പെടുത്തിയ നിങ്ങളുടെ ആദ്യ നിലയിലേക്ക് സജ്ജമാക്കുന്നു. ബാധിച്ച സേവനങ്ങൾ സാധാരണ നിലയിലേക്ക് മടങ്ങുന്നു, പരിഹാര സമയം സ്റ്റാമ്പ് ചെയ്യുന്നു, ചരിത്രം ശരിയായി വായിക്കാൻ സംഭവത്തിന്റെ അപ്ഡേറ്റുകളിലേക്ക് ഒരു വരി ചേർക്കുന്നു. സംഭവത്തെക്കുറിച്ച് മറ്റൊന്നും മാറില്ല. ഇതിനകം പരിഹരിച്ച ഒരു സംഭവത്തിൽ ഇത് ലഭ്യമല്ല.',
        'actions_delete' => '<strong>Delete</strong> &mdash; സംഭവവും അതിന്റെ അപ്ഡേറ്റുകളും നീക്കം ചെയ്യുന്നു. പഴയപടിയാക്കാൻ കഴിയില്ല, അതിനാൽ ആദ്യം ചോദിക്കും.',
        'actions_updates' => 'right-click മെനുവിൽ <strong>Show updates</strong> കൂടി ഉണ്ട്, തലക്കെട്ടിന് അരികിലുള്ള ലിങ്ക് തുറക്കുന്ന അതേ ത്രെഡ് തന്നെ.',
        'actions_tip' => '<strong>Resolve</strong> ഒരു നിലയും resolved എന്ന് അടയാളപ്പെടുത്തിയിട്ടില്ലെന്ന് പറഞ്ഞാൽ, Settings &rarr; Incident statuses-ന് കീഴിൽ ഒന്ന് ചേർത്ത് <em>Resolved</em> ടിക്ക് ചെയ്യുക. അങ്ങനെ അടയാളപ്പെടുത്തുന്നതുവരെ, നിങ്ങളുടെ ഏത് നിലയാണ് സംഭവം കഴിഞ്ഞു എന്നർത്ഥമാക്കുന്നതെന്ന് FreeITSM-ന് അറിയാൻ വഴിയില്ല.',
        'history_p2' => 'പരിഹരിച്ച സംഭവങ്ങൾ ഒരു ചരിത്ര രേഖയായി പട്ടികയിൽ ദൃശ്യമായി തുടരുന്നു. ഇത് ആവർത്തിച്ചുള്ള പ്രശ്നങ്ങൾ കണ്ടെത്താനും, മുൻ സംഭവങ്ങൾ എങ്ങനെ കൈകാര്യം ചെയ്തുവെന്ന് അവലോകനം ചെയ്യാനും, അടിസ്ഥാന പ്രശ്നങ്ങളിലേക്ക് വിരൽ ചൂണ്ടുന്ന പാറ്റേണുകൾ തിരിച്ചറിയാനും എളുപ്പമാക്കുന്നു.',
        'history_tip' => 'നിങ്ങളുടെ സംഭവ ചരിത്രം പതിവായി അവലോകനം ചെയ്യുന്നത് പതിവായി തടസ്സപ്പെടുന്ന സേവനങ്ങൾ തിരിച്ചറിയാൻ സഹായിക്കുന്നു. ഒരേ സേവനം ഒന്നിലധികം സംഭവങ്ങളിൽ പ്രത്യക്ഷപ്പെടുകയാണെങ്കിൽ, മൂലകാരണം കൂടുതൽ ആഴത്തിൽ അന്വേഷിക്കാനോ ഒരു ഇൻഫ്രാസ്ട്രക്ചർ അപ്ഗ്രേഡ് ആസൂത്രണം ചെയ്യാനോ സമയമായിരിക്കാം.',
        'vis_heading' => 'ഇന്റേണൽ കുറിപ്പുകളും എക്സ്റ്റേണൽ അപ്ഡേറ്റുകളും',
        'vis_p1' => 'കമന്റ് ബോക്സിൽ എന്തെങ്കിലും എഴുതി ഒരു സംഭവം സേവ് ചെയ്യുമ്പോഴെല്ലാം, അത് സംഭവത്തിന്റെ ടൈംലൈനിൽ ഒരു എൻട്രിയായി മാറുന്നു &mdash; ഇത് ആർക്ക് വേണ്ടിയാണെന്ന് നിങ്ങൾ തിരഞ്ഞെടുക്കുന്നു. ഒരു <strong>ഇന്റേണൽ കുറിപ്പ്</strong> നിങ്ങളുടെ ടീം മാത്രമേ കാണൂ: പ്രശ്നത്തെക്കുറിച്ച് നിങ്ങൾ എന്താണ് ചെയ്യുന്നത്, എന്താണ് ഒഴിവാക്കിയത്, ഏത് വിതരണക്കാരനെയാണ് പിന്തുടരുന്നത്. ഒരു <strong>എക്സ്റ്റേണൽ അപ്ഡേറ്റ്</strong> തടസ്സം ബാധിച്ച ആളുകൾക്കായി എഴുതുന്നു.',
        'vis_p2' => '<strong>ഇന്റേണൽ ആണ് സ്ഥിരസ്ഥിതി, ഡയലോഗ് തുറക്കുമ്പോഴെല്ലാം ഇത് ഇന്റേണലിലേക്ക് തിരികെ പോകും.</strong> പ്രസിദ്ധീകരിക്കൽ ഒരു മനഃപൂർവ്വമായ പ്രവർത്തിയായിരിക്കണം, തിരഞ്ഞെടുപ്പ് നിങ്ങൾ അവസാനം കൈകാര്യം ചെയ്ത സംഭവത്തിൽ നിന്ന് തുടരുന്നില്ല &mdash; അല്ലെങ്കിൽ ഒരു മണിക്കൂർ മുമ്പ് മറ്റെന്തെങ്കിലുമായി ബന്ധപ്പെട്ട് നിങ്ങൾ എടുത്ത ഒരു തീരുമാനം കാരണം നിങ്ങൾ പ്രസിദ്ധീകരിച്ചേക്കാം.',
        'vis_p3' => 'ടൈംലൈനിലെ ഓരോ എൻട്രിക്കും ഒരു ബാഡ്ജ് ഉണ്ട്, അതിനാൽ ഒന്നും തുറക്കാതെ തന്നെ പിന്നീട് ഏതാണ് ഏതെന്ന് നിങ്ങൾക്ക് പറയാം.',
        'vis_note' => '<strong>System &rarr; Service status on the portal</strong>-ന് കീഴിൽ ഒരു അഡ്മിനിസ്ട്രേറ്റർ ഇത് ഓണാക്കുന്നതുവരെ എൻഡ് യൂസർമാർക്ക് ഒന്നും പ്രസിദ്ധീകരിക്കില്ല. അതുവരെ, <em>external</em> തിരഞ്ഞെടുക്കുന്നത് അപ്ഡേറ്റിനെ അടയാളപ്പെടുത്തുന്നു, തിരഞ്ഞെടുപ്പിന് താഴെയുള്ള സൂചന നിങ്ങളുടെ ടീമിന് പുറത്തുള്ളവർ ഇത് ഇനിയും കാണില്ലെന്ന് വ്യക്തമായി പറയുന്നു. ഈ ഫീച്ചർ ഉണ്ടാകുന്നതിന് മുമ്പ് എഴുതിയതെല്ലാം ഇന്റേണൽ ആണ്, ഇന്റേണൽ ആയി തുടരും.',
        'corr_heading' => 'ഒരു ടൈപ്പോ ശരിയാക്കൽ, എന്താണ് ഒരു അപ്ഡേറ്റായി കണക്കാക്കുന്നത്',
        'corr_p1' => 'ടൈംലൈനിലെ ഓരോ എൻട്രിക്കും ഒരു <strong>correct</strong>ഉം ഒരു <strong>remove</strong> പ്രവർത്തനവും ഉണ്ട്. തിരുത്തൽ നിലവിലുള്ള വാക്കുകൾ മാറ്റുന്നു, അതിനാൽ ഒരു ടൈപ്പോ ആദ്യത്തേതിന് ഏതാനും മിനിറ്റുകൾക്ക് ശേഷം ഏതാണ്ട് സമാനമായ രണ്ടാമത്തെ സന്ദേശമായി മാറില്ല &mdash; കസ്റ്റമർമാർ വായിക്കുന്ന ഒരു പേജിൽ ഇത് അശ്രദ്ധയായി തോന്നും.',
        'corr_p2' => 'ഒരു എൻട്രി <strong>ആർക്ക് കാണാം</strong> എന്നത് പിന്നീടും മാറ്റാം: പുറത്തുപോകേണ്ടിയിരുന്ന ഒരു ഇന്റേണൽ കുറിപ്പ്, വീണ്ടും ടൈപ്പ് ചെയ്യാതെ തന്നെ പ്രസിദ്ധീകരിക്കാം, തെറ്റായി പ്രസിദ്ധീകരിച്ച ഒന്ന്, അത് സംഭവിച്ചു എന്ന രേഖ നഷ്ടപ്പെടാതെ തന്നെ തിരികെ വലിക്കാം. എൻട്രി <em>status</em>-നെക്കുറിച്ചും <em>service impacts</em>-നെക്കുറിച്ചും പറയുന്നത് മാറ്റാൻ കഴിയില്ല &mdash; ആ നിമിഷം ശരിയായിരുന്നത് അതാണ്.',
        'corr_p3' => 'പറയാൻ പുതിയതായി എന്തെങ്കിലും ഉള്ളപ്പോൾ മാത്രമേ ഒരു സംഭവം സേവ് ചെയ്യുന്നത് ടൈംലൈനിലേക്ക് ചേർക്കുകയുള്ളൂ: നില മാറി, വാചകം മാറി, അല്ലെങ്കിൽ ബാധിച്ച സേവനങ്ങൾ മാറി. ഒരു സംഭവത്തിന്റെ പേര് മാറ്റുന്നത് ഒരു പുതിയ സന്ദേശമല്ല, ഒന്ന് തുറന്ന് Save അമർത്തുന്നത് ഒന്നും പോസ്റ്റ് ചെയ്യില്ല.',
        'corr_note' => 'പുതിയ വാചകമില്ലാത്ത ഒരു നില മാറ്റം, മുമ്പത്തെ വാചകം ആവർത്തിക്കുന്നതിന് പകരം സ്വന്തമായി രേഖപ്പെടുത്തുന്നു, അതിനാൽ ഒരു വായനക്കാരൻ &ldquo;Investigating &mdash; we are aware of delays&rdquo; എന്നതിന് ശേഷം &ldquo;Resolved &mdash; we are aware of delays&rdquo; എന്ന് കാണില്ല.',
        'settings_heading' => 'ക്രമീകരണങ്ങൾ',
        'settings_p1' => 'നിങ്ങളുടെ സേവന കാറ്റലോഗ് നിർമ്മിക്കുകയും പരിപാലിക്കുകയും ചെയ്യുന്നിടമാണ് ക്രമീകരണ പേജ്. നില ഡാഷ്ബോർഡിൽ പ്രത്യക്ഷപ്പെടുന്ന എല്ലാ സേവനവും ആദ്യം ഇവിടെ ക്രമീകരിക്കണം.',
        'settings_step1_html' => '<strong>ഒരു സേവനം ചേർക്കുക</strong> &mdash; "ചേർക്കുക" ക്ലിക്ക് ചെയ്ത് ഒരു പേര് (ഉദാ. "ഇമെയിൽ", "VPN", "ERP സിസ്റ്റം") നൽകുകയും സേവനം എന്ത് ചെയ്യുന്നു എന്ന് വിശദീകരിക്കുന്ന ഒരു ഐച്ഛിക വിവരണവും നൽകുക.',
        'settings_step2_html' => '<strong>പ്രദർശന ക്രമം സജ്ജമാക്കുക</strong> &mdash; ഡാഷ്ബോർഡ് ഗ്രിഡിൽ സേവനം എവിടെ പ്രത്യക്ഷപ്പെടുന്നു എന്ന് ക്രമ നമ്പർ നിയന്ത്രിക്കുന്നു. കുറഞ്ഞ നമ്പറുകൾ ആദ്യം പ്രത്യക്ഷപ്പെടുന്നു, അതിനാൽ നിങ്ങളുടെ ഏറ്റവും നിർണായക സേവനങ്ങൾ മുകളിൽ വയ്ക്കുക.',
        'settings_step3_html' => '<strong>സജീവം/നിഷ്ക്രിയം ടോഗിൾ ചെയ്യുക</strong> &mdash; ഒരു സേവനം നിഷ്ക്രിയമാക്കുന്നത് അത് ഇല്ലാതാക്കാതെ ഡാഷ്ബോർഡിൽ നിന്ന് നീക്കം ചെയ്യുന്നു. ഡീകമ്മീഷൻ ചെയ്ത സേവനങ്ങൾക്കോ കാലികമായ സിസ്റ്റങ്ങൾക്കോ ഇത് ഉപയോഗപ്രദമാണ്.',
        'settings_step4_html' => '<strong>തിരുത്തുകയോ ഇല്ലാതാക്കുകയോ ചെയ്യുക</strong> &mdash; സേവന വിശദാംശങ്ങൾ പുതുക്കാനോ ഒരു സേവനം പൂർണ്ണമായും നീക്കം ചെയ്യാനോ ഓരോ വരിയിലെയും പ്രവർത്തന ബട്ടണുകൾ ഉപയോഗിക്കുക. ചരിത്രപരമായ സംഭവ ലിങ്കുകൾ കേടുകൂടാതെ നിലനിൽക്കാൻ ഇല്ലാതാക്കുന്നതിനേക്കാൾ തിരുത്തലാണ് എപ്പോഴും അഭികാമ്യം.',
        'settings_tip' => 'നിങ്ങളുടെ സേവന കാറ്റലോഗിനെ നിങ്ങളുടെ നില പേജിന്റെ അടിത്തറയായി കരുതുക. പേരുകളും വിവരണങ്ങളും ശരിയാക്കാൻ സമയം ചെലവഴിക്കുക &mdash; നിങ്ങളുടെ ഐടി പരിസ്ഥിതിയുടെ ആരോഗ്യം പരിശോധിക്കുമ്പോൾ നിങ്ങളുടെ ഉപയോക്താക്കളും പങ്കാളികളും കാണുന്നത് ഇവയാണ്.',
        'tips_heading' => 'പെട്ടെന്നുള്ള നുറുങ്ങുകൾ',
        'tip_communicate_title' => 'നേരത്തെ അറിയിക്കുക',
        'tip_communicate_desc' => 'എല്ലാ വിശദാംശങ്ങളും ഇല്ലെങ്കിലും, എന്തെങ്കിലും തെറ്റ് സംഭവിച്ചതായി അറിയുമ്പോൾ തന്നെ ഒരു സംഭവം പോസ്റ്റ് ചെയ്യുക. ഒരു പ്രശ്നം വേഗത്തിൽ അംഗീകരിക്കുന്നത് നിങ്ങളുടെ ഉപയോക്താക്കളുമായി വിശ്വാസം വളർത്തുന്നു.',
        'tip_update_title' => 'പതിവായി പുതുക്കുക',
        'tip_update_desc' => 'പതിവ് നില പുതുക്കലുകൾ &mdash; ഒന്നും മാറിയിട്ടില്ലെങ്കിലും &mdash; പ്രശ്നം സജീവമായി പരിഹരിക്കുന്നുവെന്ന് ഉപയോക്താക്കളെ കാണിക്കുന്നു. നിശ്ശബ്ദത നിരാശയും സപ്പോർട്ട് ടിക്കറ്റുകളും വളർത്തുന്നു.',
        'tip_review_title' => 'പാറ്റേണുകൾ അവലോകനം ചെയ്യുക',
        'tip_review_desc' => 'നിങ്ങളുടെ സംഭവ ചരിത്രം പതിവായി പരിശോധിക്കുക. ഒരേ സേവനം ആവർത്തിച്ച് പ്രത്യക്ഷപ്പെടുകയാണെങ്കിൽ, അത് മുൻകൂട്ടി പരിഹരിക്കേണ്ട ഒരു ആഴത്തിലുള്ള ഇൻഫ്രാസ്ട്രക്ചർ പ്രശ്നത്തിലേക്ക് വിരൽ ചൂണ്ടിയേക്കാം.',
        'tip_maintenance_title' => 'പരിപാലനം ആസൂത്രണം ചെയ്യുക',
        'tip_maintenance_desc' => 'ആസൂത്രണം ചെയ്ത ജോലിക്കായി പരിപാലനം ആഘാത നിലവാരം ഉപയോഗിക്കുക. മുൻകൂട്ടി ഒരു സംഭവം സൃഷ്ടിക്കുന്നത് ഷെഡ്യൂൾ ചെയ്ത ഡൗൺടൈമിനെക്കുറിച്ച് അത് സംഭവിക്കുന്നതിന് മുമ്പ് ഉപയോക്താക്കളെ അറിയിക്കുന്നു.',
    ],
